CREATE TABLE journal_entries (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,journal_no VARCHAR(30) NOT NULL,journal_date DATE NOT NULL,description VARCHAR(500) NOT NULL,reference VARCHAR(190) NULL,status VARCHAR(10) NOT NULL DEFAULT 'draft',source_type VARCHAR(50) NULL,source_id BIGINT UNSIGNED NULL,source_reference VARCHAR(190) NULL,created_by BIGINT UNSIGNED NOT NULL,posted_by BIGINT UNSIGNED NULL,posted_at DATETIME NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_journal_entries_no(journal_no),UNIQUE KEY uq_journal_entries_source(source_type,source_id),KEY idx_journal_entries_date_status(journal_date,status),CONSTRAINT fk_journal_entries_created FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT fk_journal_entries_posted FOREIGN KEY(posted_by) REFERENCES users(id) ON DELETE RESTRICT,CONSTRAINT chk_journal_entries_status CHECK(status IN('draft','posted')),CONSTRAINT chk_journal_entries_source CHECK((source_type IS NULL AND source_id IS NULL) OR(source_type IS NOT NULL AND source_id IS NOT NULL)),CONSTRAINT chk_journal_entries_audit CHECK((status='draft' AND posted_by IS NULL AND posted_at IS NULL) OR(status='posted' AND posted_by IS NOT NULL AND posted_at IS NOT NULL))) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
